"""Private attachment storage. Object keys are generated by the server only."""

import os
import re
from pathlib import Path
from typing import Protocol

import boto3

from app.core.config import get_settings

MAX_IMAGE_BYTES = 5 * 1024 * 1024
_FILENAME = re.compile(r"[0-9a-f]{32}\.(jpg|png|webp)\Z")


class AttachmentStorage(Protocol):
    def put(self, key: str, content: bytes, mime_type: str) -> None: ...
    def get(self, key: str) -> bytes: ...
    def delete(self, key: str) -> None: ...


def _validate_key(key: str) -> None:
    if key.startswith("/") or "\\" in key or any(part in {"", ".", ".."} for part in key.split("/")):
        raise ValueError("Invalid attachment key")
    if not _FILENAME.fullmatch(key.rsplit("/", 1)[-1]):
        raise ValueError("Invalid attachment key")


class LocalStorage:
    def __init__(self, root: Path) -> None:
        self.root = root.resolve()

    def _path(self, key: str) -> Path:
        _validate_key(key)
        if "/" in key:
            raise ValueError("Invalid local attachment key")
        path = self.root / key
        if path.is_symlink():
            raise ValueError("Invalid local attachment path")
        return path

    def put(self, key: str, content: bytes, mime_type: str) -> None:
        self.root.mkdir(parents=True, exist_ok=True, mode=0o700)
        path = self._path(key)
        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        try:
            with os.fdopen(descriptor, "wb") as output:
                output.write(content)
        except Exception:
            path.unlink(missing_ok=True)
            raise

    def get(self, key: str) -> bytes:
        descriptor = os.open(self._path(key), os.O_RDONLY | os.O_NOFOLLOW)
        with os.fdopen(descriptor, "rb") as source:
            content = source.read(MAX_IMAGE_BYTES + 1)
        if not content or len(content) > MAX_IMAGE_BYTES:
            raise ValueError("Invalid stored attachment")
        return content

    def delete(self, key: str) -> None:
        self._path(key).unlink(missing_ok=True)


class S3Storage:
    def __init__(self) -> None:
        settings = get_settings()
        if not settings.aws_region or not settings.aws_bucket_name:
            raise ValueError("S3 storage requires AWS_REGION and AWS_BUCKET_NAME")
        self.bucket = settings.aws_bucket_name
        credentials = {}
        if settings.aws_access_key_id and settings.aws_secret_access_key:
            credentials = {
                "aws_access_key_id": settings.aws_access_key_id.get_secret_value(),
                "aws_secret_access_key": settings.aws_secret_access_key.get_secret_value(),
            }
        self.client = boto3.client("s3", region_name=settings.aws_region, **credentials)

    def put(self, key: str, content: bytes, mime_type: str) -> None:
        _validate_key(key)
        # No public ACL; bucket Block Public Access is a deployment prerequisite.
        self.client.put_object(Bucket=self.bucket, Key=key, Body=content, ContentType=mime_type, IfNoneMatch="*")

    def get(self, key: str) -> bytes:
        _validate_key(key)
        response = self.client.get_object(Bucket=self.bucket, Key=key)
        body = response["Body"]
        try:
            content = body.read(MAX_IMAGE_BYTES + 1)
        finally:
            body.close()
        if not content or len(content) > MAX_IMAGE_BYTES:
            raise ValueError("Invalid stored attachment")
        return content

    def delete(self, key: str) -> None:
        _validate_key(key)
        self.client.delete_object(Bucket=self.bucket, Key=key)


def get_storage(provider: str) -> AttachmentStorage:
    if provider == "local":
        return LocalStorage(get_settings().local_upload_dir)
    if provider == "s3":
        return S3Storage()
    raise ValueError("Unsupported attachment storage provider")
